// ============================================================================
// JAGAT Colony — Lesson Memory Engine v0
// Stores lesson learned from completed mission outcome summaries.
//
// Storage: Redis only. TIDAK menulis ke Qdrant sovereign memory.
// Source: Only from MissionOutcomeSummary (generated by completeMissionWithSummary).
// Extraction: Deterministic, no LLM calls.
//
// Provenance per lesson: missionId, taskIds, score, createdAt, source.
// ============================================================================

import { getRedisClient } from "../services/redis.service.js";
import {
  type ColonyLesson,
  type LessonCategory,
  type MissionOutcomeSummary,
  type PlannerLessonAdvisory,
  type PlannerLessonContext,
  REDIS_KEYS,
} from "./types.js";
import { getMission } from "./mission-engine.js";
import { getTasksByMission } from "./task-engine.js";

// ── ID Generator ────────────────────────────────────────────────────────────

async function nextLessonId(): Promise<string> {
  const redis = getRedisClient();
  const seq = await redis.incr(REDIS_KEYS.lessonSequence());
  const date = new Date().toISOString().slice(0, 10).replace(/-/g, "");
  return `LESSON-${date}-${String(seq).padStart(3, "0")}`;
}

// ── Category Classification ─────────────────────────────────────────────────

/**
 * Classify a lesson category from mission outcome summary.
 * Deterministic — no LLM.
 */
function classifyLessonCategory(summary: MissionOutcomeSummary): LessonCategory {
  const { avgQualityScore, blockedCount, reviewCount, runningCount, totalTasks } = summary;

  // Quality high: avg score ≥ 80
  if (avgQualityScore !== null && avgQualityScore >= 80) {
    return "quality_high";
  }

  // Blocked pattern: 2+ blocked tasks — systemic blocker is more important than low quality.
  // A mission with 2+ blocked tasks signals a structural/pipeline problem that should be
  // surfaced even if the remaining done tasks have low quality scores.
  if (blockedCount >= 2) {
    return "blocked_pattern";
  }

  // Quality low: avg score < 60
  if (avgQualityScore !== null && avgQualityScore < 60) {
    return "quality_low";
  }

  // Scope change: majority of tasks stuck in review or running
  if (totalTasks > 0 && (reviewCount + runningCount) / totalTasks > 0.5) {
    return "scope_change";
  }

  return "general";
}

/**
 * Generate a lesson title from mission title and category.
 */
function generateLessonTitle(missionTitle: string, category: LessonCategory): string {
  const prefix: Record<LessonCategory, string> = {
    quality_high: "[HIGH QUALITY]",
    quality_low: "[LOW QUALITY]",
    blocked_pattern: "[BLOCKED PATTERN]",
    scope_change: "[SCOPE CHANGE]",
    general: "[LESSON]",
  };
  return `${prefix[category]} ${missionTitle}`;
}

/**
 * Collect unique tags from mission phase, priority, and task tags/statuses.
 */
function collectTags(
  missionPhase: string,
  missionPriority: string,
  tasks: Array<{ tags?: string[]; status: string }>,
): string[] {
  const tagSet = new Set<string>();
  tagSet.add(`phase:${missionPhase}`);
  tagSet.add(`priority:${missionPriority}`);

  for (const task of tasks) {
    if (task.tags) {
      for (const tag of task.tags) {
        tagSet.add(tag);
      }
    }
    tagSet.add(`status:${task.status}`);
  }

  return Array.from(tagSet).sort();
}

// -- Planner Advisory Scoring ------------------------------------------------

const CATEGORY_PLANNER_WEIGHTS: Record<LessonCategory, number> = {
  blocked_pattern: 6,
  quality_low: 5,
  scope_change: 4,
  quality_high: 3,
  general: 2,
};

const LESSON_QUERY_STOPWORDS = new Set([
  "agar",
  "akan",
  "atau",
  "buat",
  "bisa",
  "dari",
  "dan",
  "dengan",
  "ini",
  "itu",
  "jadi",
  "jika",
  "karena",
  "kita",
  "lagi",
  "lebih",
  "melalui",
  "untuk",
  "yang",
  "the",
  "and",
  "for",
  "from",
  "into",
  "with",
  "task",
  "mission",
  "planner",
]);

function tokenizeForLessonQuery(input: string): string[] {
  const matches = input.toLowerCase().match(/[a-z0-9]+/g) ?? [];
  return Array.from(new Set(matches.filter((token) => token.length >= 3 && !LESSON_QUERY_STOPWORDS.has(token))));
}

function scoreLessonForPlanner(
  lesson: ColonyLesson,
  queryTokens: Set<string>,
  missionId?: string,
): { score: number; reasons: string[] } {
  let score = 0;
  const reasons: string[] = [];

  if (missionId && lesson.missionId === missionId) {
    score += 8;
    reasons.push("same_mission");
  }

  const titleTokens = new Set(tokenizeForLessonQuery(lesson.title));
  const contentTokens = new Set(tokenizeForLessonQuery(lesson.content));
  const tagTokens = new Set(tokenizeForLessonQuery(lesson.tags.join(" ")));
  let matchedTokens = 0;

  for (const token of queryTokens) {
    let tokenScore = 0;
    if (titleTokens.has(token)) tokenScore += 2;
    if (tagTokens.has(token)) tokenScore += 2;
    if (contentTokens.has(token)) tokenScore += 1;

    if (tokenScore > 0) {
      matchedTokens += 1;
      score += Math.min(tokenScore, 3);
      if (reasons.length < 8) reasons.push(`matched:${token}`);
    }
  }

  if (score === 0) {
    return { score: 0, reasons: [] };
  }

  score += CATEGORY_PLANNER_WEIGHTS[lesson.category];
  reasons.push(`category:${lesson.category}`);

  if (lesson.category === "blocked_pattern") {
    score += 2;
    reasons.push("blocked_pattern_priority");
  }

  if (lesson.score !== null && lesson.score < 60) {
    score += 2;
    reasons.push("low_score");
  }

  if (matchedTokens >= 3) {
    score += 2;
    reasons.push("multi_token_match");
  }

  return { score, reasons };
}

// ── Core API ────────────────────────────────────────────────────────────────

/**
 * Create a lesson from a completed mission's outcome summary.
 *
 * Requirements:
 * - Mission must exist and have status "completed"
 * - Mission must have an outcomeSummary (generated by completeMissionWithSummary)
 *
 * Idempotent: if a lesson already exists for this mission, returns the existing one.
 *
 * Does NOT write to Qdrant. Does NOT use LLM.
 */
export async function createLessonFromMission(missionId: string): Promise<ColonyLesson> {
  const redis = getRedisClient();

  // 1. Validate mission exists and is completed
  const mission = await getMission(missionId);
  if (!mission) {
    throw new Error(`Mission ${missionId} not found`);
  }
  if (mission.status !== "completed") {
    throw new Error(`Mission ${missionId} is not completed (status: ${mission.status}). Only completed missions can generate lessons.`);
  }
  if (!mission.outcomeSummary) {
    throw new Error(`Mission ${missionId} has no outcome summary. Run completeMissionWithSummary() first.`);
  }

  // 2. Idempotency check — if lesson already exists for this mission, return it
  const existingIds = await redis.smembers(REDIS_KEYS.lessonsByMission(missionId));
  for (const existingId of existingIds) {
    const existing = await getLesson(existingId);
    if (existing) return existing;
  }

  const summary = mission.outcomeSummary;

  // 3. Gather task IDs
  const tasks = await getTasksByMission(missionId);
  const taskIds = tasks.map((t) => t.taskId);

  // 4. Classify category
  const category = classifyLessonCategory(summary);

  // 5. Generate title
  const title = generateLessonTitle(mission.title, category);

  // 6. Build content from summary (structured, no LLM)
  const content = summary.summary;

  // 7. Collect tags
  const tags = collectTags(mission.phase, mission.priority, tasks);

  // 8. Create lesson
  const lessonId = await nextLessonId();
  const now = new Date().toISOString();

  const lesson: ColonyLesson = {
    lessonId,
    missionId,
    taskIds,
    category,
    title,
    content,
    score: summary.avgQualityScore,
    createdAt: now,
    source: "mission_outcome",
    tags,
  };

  // 9. Store in Redis
  await redis.set(REDIS_KEYS.lesson(lessonId), JSON.stringify(lesson));
  await redis.sadd(REDIS_KEYS.lessonIndex(), lessonId);
  await redis.sadd(REDIS_KEYS.lessonsByMission(missionId), lessonId);

  return lesson;
}

/**
 * Get a single lesson by ID.
 */
export async function getLesson(lessonId: string): Promise<ColonyLesson | null> {
  const redis = getRedisClient();
  const data = await redis.get(REDIS_KEYS.lesson(lessonId));
  return data ? (JSON.parse(data) as ColonyLesson) : null;
}

/**
 * List lessons with optional filters.
 */
export async function listLessons(opts?: {
  category?: LessonCategory;
  missionId?: string;
  limit?: number;
}): Promise<ColonyLesson[]> {
  const redis = getRedisClient();

  let ids: string[];

  if (opts?.missionId) {
    // Filter by mission
    ids = await redis.smembers(REDIS_KEYS.lessonsByMission(opts.missionId));
  } else {
    // All lessons
    ids = await redis.smembers(REDIS_KEYS.lessonIndex());
  }

  const lessons: ColonyLesson[] = [];
  for (const id of ids) {
    const lesson = await getLesson(id);
    if (!lesson) continue;

    // Apply category filter
    if (opts?.category && lesson.category !== opts.category) continue;

    lessons.push(lesson);
  }

  // Sort by creation date descending (newest first)
  lessons.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

  // Apply limit
  if (opts?.limit && opts.limit > 0) {
    return lessons.slice(0, opts.limit);
  }

  return lessons;
}

/**
 * Get all lessons for a specific mission.
 */
export async function getLessonsByMission(missionId: string): Promise<ColonyLesson[]> {
  return listLessons({ missionId });
}

/**
 * Retrieve lessons that can advise planner/directive generation.
 *
 * This is intentionally read-only:
 * - Redis only
 * - no Qdrant writes
 * - no LLM calls
 * - no task creation
 * - no auto-replan or auto-retry
 */
export async function getPlannerLessonContext(opts: {
  directive: string;
  missionId?: string;
  categories?: LessonCategory[];
  limit?: number;
  minRelevanceScore?: number;
}): Promise<PlannerLessonContext> {
  const query = opts.directive.trim();
  const queryTokens = new Set(tokenizeForLessonQuery(query));
  const limit = Math.min(Math.max(opts.limit ?? 5, 1), 10);
  const minRelevanceScore = opts.minRelevanceScore ?? 3;
  const generatedAt = new Date().toISOString();

  if (queryTokens.size === 0 && !opts.missionId) {
    return {
      query,
      ...(opts.missionId ? { missionId: opts.missionId } : {}),
      generatedAt,
      storage: "redis_only",
      actionPolicy: "advisory_only",
      lessons: [],
    };
  }

  const lessons = await listLessons(opts.missionId ? { missionId: opts.missionId } : undefined);
  const allowedCategories = opts.categories?.length ? new Set(opts.categories) : null;

  const scored: PlannerLessonAdvisory[] = lessons
    .filter((lesson) => !allowedCategories || allowedCategories.has(lesson.category))
    .map((lesson) => {
      const { score, reasons } = scoreLessonForPlanner(lesson, queryTokens, opts.missionId);
      return {
        ...lesson,
        relevanceScore: score,
        relevanceReasons: reasons,
      };
    })
    .filter((lesson) => lesson.relevanceScore >= minRelevanceScore)
    .sort((a, b) => {
      if (b.relevanceScore !== a.relevanceScore) return b.relevanceScore - a.relevanceScore;
      return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
    })
    .slice(0, limit);

  return {
    query,
    ...(opts.missionId ? { missionId: opts.missionId } : {}),
    generatedAt,
    storage: "redis_only",
    actionPolicy: "advisory_only",
    lessons: scored,
  };
}

// ── Cross-Mission Pattern Detection ─────────────────────────────────────────

export interface CrossMissionPattern {
  patternType: "recurring_category" | "quality_trend" | "tag_cluster" | "blocked_reason";
  description: string;
  frequency: number;
  affectedMissions: string[];
  confidence: number; // 0-1
}

export interface PatternDetectionResult {
  totalLessons: number;
  totalMissions: number;
  patterns: CrossMissionPattern[];
  generatedAt: string;
}

/**
 * Detect patterns across multiple missions.
 * Read-only, deterministic, no LLM. Advisory only.
 */
export async function detectCrossMissionPatterns(): Promise<PatternDetectionResult> {
  const lessons = await listLessons();
  const patterns: CrossMissionPattern[] = [];
  const generatedAt = new Date().toISOString();

  // Group by mission
  const byMission = new Map<string, ColonyLesson[]>();
  for (const lesson of lessons) {
    const existing = byMission.get(lesson.missionId) ?? [];
    existing.push(lesson);
    byMission.set(lesson.missionId, existing);
  }

  // Pattern 1: Recurring categories across missions
  const categoryCounts = new Map<LessonCategory, Set<string>>();
  for (const lesson of lessons) {
    const missions = categoryCounts.get(lesson.category) ?? new Set();
    missions.add(lesson.missionId);
    categoryCounts.set(lesson.category, missions);
  }
  for (const [category, missions] of categoryCounts) {
    if (missions.size >= 2) {
      patterns.push({
        patternType: "recurring_category",
        description: `Category "${category}" appears in ${missions.size} missions`,
        frequency: missions.size,
        affectedMissions: Array.from(missions),
        confidence: Math.min(missions.size / 5, 1),
      });
    }
  }

  // Pattern 2: Quality trend (average score over time)
  const scoredLessons = lessons.filter((l) => l.score !== null);
  if (scoredLessons.length >= 3) {
    const sorted = [...scoredLessons].sort((a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime());
    const firstHalf = sorted.slice(0, Math.floor(sorted.length / 2));
    const secondHalf = sorted.slice(Math.floor(sorted.length / 2));
    const avgFirst = firstHalf.reduce((sum, l) => sum + (l.score ?? 0), 0) / firstHalf.length;
    const avgSecond = secondHalf.reduce((sum, l) => sum + (l.score ?? 0), 0) / secondHalf.length;
    if (Math.abs(avgSecond - avgFirst) >= 10) {
      patterns.push({
        patternType: "quality_trend",
        description: avgSecond > avgFirst ? "Quality improving over time" : "Quality declining over time",
        frequency: scoredLessons.length,
        affectedMissions: Array.from(new Set(scoredLessons.map((l) => l.missionId))),
        confidence: Math.min(scoredLessons.length / 10, 1),
      });
    }
  }

  // Pattern 3: Blocked reason clusters
  const blockedLessons = lessons.filter((l) => l.category === "blocked_pattern");
  if (blockedLessons.length >= 2) {
    patterns.push({
      patternType: "blocked_reason",
      description: `${blockedLessons.length} missions with blocked patterns`,
      frequency: blockedLessons.length,
      affectedMissions: Array.from(new Set(blockedLessons.map((l) => l.missionId))),
      confidence: Math.min(blockedLessons.length / 3, 1),
    });
  }

  return {
    totalLessons: lessons.length,
    totalMissions: byMission.size,
    patterns,
    generatedAt,
  };
}
